body.addEventListener('input',event=>{const f=event.target.closest('form');if(!f)return;if(f.dataset.form==='memory-card'){const d=new FormData(f);memoryDraft={photoIds:d.getAll('memory-photo'),includeAvatar:d.get('memory-avatar')==='on',consent:event.target.name==='memory-confirm'&&d.get('memory-confirm')==='on'};memoryStatus={};renderPanel(false);return;}if(f.dataset.form==='profile')controller.setDraft('profile',profileFrom(f));if(f.dataset.form==='create'){const d=new FormData(f);controller.setDraft('room',{title:d.get('title'),venue:d.get('venue'),songId:d.get('songId')});}if(f.dataset.form==='participation'&&event.target.name==='participation')participationDraft=event.target.value;if(f.dataset.form==='upload'&&event.target.name==='visibility'){const d=photoDraft||state.drafts.photo;if(d){photoDraft={...d,visibility:event.target.value};controller.setDraft('photo',photoDraft);}}});
body.addEventListener('change',async event=>{if(event.target.name!=='photo')return;const file=event.target.files?.[0];if(!file)return;const generation=++photoInputGeneration,target=room()?.id;try{if(file.size>20*1024*1024)throw Error('请选择 20 MB 以内的照片');if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('请选择 JPG、PNG 或 WebP 照片');const image=await createImageBitmap(file);try{let scale=Math.min(1,1600/Math.max(image.width,image.height)),url;for(let n=0;n<6;n++){const canvas=document.createElement('canvas');canvas.width=Math.round(image.width*scale);canvas.height=Math.round(image.height*scale);canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);url=canvas.toDataURL('image/jpeg',.82-n*.055);if(url.length<390000)break;scale*=.8;}if(url.length>=390000)throw Error('这张照片太复杂，请裁剪后再试');if(generation!==photoInputGeneration||target!==room()?.id)return;photoDraft={roomId:target,dataUrl:url,visibility:'private'};controller.setDraft('photo',photoDraft);if(panelKind==='upload')renderPanel(false);}finally{image.close();}}catch(error){failure(error);}});
body.addEventListener('submit',event=>{event.preventDefault();const f=event.target,d=new FormData(f),kind=f.dataset.form;if(kind==='memory-card'){void memoryExporter.run({...memoryDraft,photoIds:[...memoryDraft.photoIds]}).catch(error=>{memoryDraft.consent=false;memoryStatus={...memoryStatus,error:{message:error.message}};if(panelKind==='memory-card')renderPanel(false);});return;}if(kind==='preview')void action(()=>controller.previewRoom(d.get('code')),()=>openPanel('preview'));if(kind==='profile')void action(()=>controller.establishIdentity(profileFrom(f),{replaceInvalid:d.get('replace')==='on'}),profileSaved);if(kind==='create'){const payload={title:d.get('title'),venue:d.get('venue'),songId:d.get('songId'),joinConsent:d.get('consent')==='on',participation:d.get('participation')||'quiet'};void action(()=>controller.createRoom(payload),arrivalFinished);}if(kind==='join')void action(()=>controller.joinRoom(f.dataset.code,{joinConsent:d.get('consent')==='on',participation:d.get('participation')||'quiet'}),arrivalFinished);if(kind==='participation'){const mode=d.get('participation'),member=myParticipation();void action(()=>controller.setParticipation(mode,{revision:member?.participationRevision}),()=>{if(participationDraft===mode)participationDraft=null;toast('参与方式已更新：'+participationLabel(myParticipation()));renderPanel(false);});}if(kind==='upload'){const draft=photoDraft||state.drafts.photo,target=f.dataset.room;if(!validDraftImage(draft?.dataUrl)||draft.roomId!==target||room()?.id!==target){toast('现场已切换，请重新选择要上传的照片');return;}const reviewed={...draft,visibility:d.get('visibility')};controller.setDraft('photo',reviewed);const submittedVersion=controller.getState().draftVersions.photo,submittedInput=photoInputGeneration;void action(()=>controller.uploadPhoto(reviewed.dataUrl,reviewed.visibility,{roomId:target}),()=>{const current=controller.getState();if(current.draftVersions.photo===submittedVersion&&submittedInput===photoInputGeneration&&JSON.stringify(current.drafts.photo)===JSON.stringify(reviewed)){photoDraft=null;controller.setDraft('photo',null);openPanel('wall');}toast(reviewed.visibility==='private'?'已保存，只有自己可见':'已分享给本场成员');});}});
