async function saveWardrobeProfile(profile,options){
 const wasMissing=state.identity.status==='missing',returnTo=wardrobeReturn,navigation=navEpoch;
 controller.setDraft('profile',profile);
 const result=state.identity.status==='ready'?await controller.saveProfile(profile,{revision:options.revision}):await controller.establishIdentity(profile);
 if(result?.applied===false)throw Error('身份已变化，未覆盖当前小人');
 if(joined())void controller.refreshRoom().catch(()=>toast('小人已保存，同场画面会在恢复连接后更新'));
 toast('小人已保存，下次碰面也能认出你');
 if(wasMissing&&navigation===navEpoch&&returnTo){
  if(returnTo.kind==='preview'&&state.preview?.code===returnTo.code)openPanel('preview');
  else if(returnTo.kind==='create')openPanel('create');
 }
 return result;
}
